from __future__ import annotations


_ALIGNMENTS = ("left", "right", "center")


def _escape_cell(value: object) -> str:
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _column_widths(
    header: list[str], rows: list[list[str]]
) -> list[int]:
    widths = [max(3, len(cell)) for cell in header]
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    return widths


def _pad_cell(text: str, width: int, align: str | None) -> str:
    gap = width - len(text)
    if align == "right":
        return " " * gap + text
    if align == "center":
        left = gap // 2
        return " " * left + text + " " * (gap - left)
    return text + " " * gap


def _delimiter_cell(width: int, align: str | None) -> str:
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def _normalize_align(align: list[str | None] | None, columns: int) -> list[str | None]:
    if align is None:
        return [None] * columns
    if not isinstance(align, (list, tuple)):
        raise ValueError("align must be a list")
    if len(align) != columns:
        raise ValueError("align must have one entry per column")
    normalized = list(align)
    for value in normalized:
        if value is not None and value not in _ALIGNMENTS:
            raise ValueError("invalid alignment: {!r}".format(value))
    return normalized


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_escape_cell(value) for value in header]
    columns = len(header_cells)
    aligns = _normalize_align(align, columns)

    body: list[list[str]] = []
    for row in rows:
        cells = [_escape_cell(value) for value in row]
        if len(cells) > columns:
            raise ValueError("row has more cells than the header")
        cells.extend([""] * (columns - len(cells)))
        body.append(cells)

    widths = _column_widths(header_cells, body)

    lines = [_line([_pad_cell(cell, widths[i], aligns[i]) for i, cell in enumerate(header_cells)])]
    lines.append(_line([_delimiter_cell(widths[i], aligns[i]) for i in range(columns)]))
    for row in body:
        lines.append(_line([_pad_cell(cell, widths[i], aligns[i]) for i, cell in enumerate(row)]))
    return "\n".join(lines)


def _split_cells(line: str) -> tuple[list[str], bool]:
    """Split a line on unescaped pipes, unescaping ``\\|`` in cells."""
    cells: list[str] = []
    buffer: list[str] = []
    trailing_separator = False
    index = 0
    while index < len(line):
        char = line[index]
        if char == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            buffer.append("|")
            trailing_separator = False
            index += 2
            continue
        if char == "|":
            cells.append("".join(buffer))
            buffer = []
            trailing_separator = True
            index += 1
            continue
        buffer.append(char)
        trailing_separator = False
        index += 1
    cells.append("".join(buffer))
    return cells, trailing_separator


def _parse_line(line: str) -> list[str]:
    stripped = line.strip()
    cells, trailing_separator = _split_cells(stripped)
    if stripped.startswith("|"):
        cells.pop(0)
    if trailing_separator and cells:
        cells.pop()
    return [cell.strip() for cell in cells]


def _parse_delimiter(cell: str) -> str | None:
    left = cell.startswith(":")
    right = cell.endswith(":")
    core = cell[1:] if left else cell
    if right:
        core = core[:-1]
    if not core or core.strip("-"):
        raise ValueError("invalid delimiter cell: {!r}".format(cell))
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")

    header = _parse_line(lines[0])
    delimiter = _parse_line(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has the wrong number of cells")
    aligns = [_parse_delimiter(cell) for cell in delimiter]

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _parse_line(line)
        if len(cells) != len(header):
            raise ValueError("row has the wrong number of cells")
        rows.append(cells)
    return header, rows, aligns

